mapper.select:
SELECT *
FROM dungeon d
WHERE d.id = #{dungeonId}

SELECT DISTINCT d.*
  FROM dungeon d
  JOIN dungeon_attraction da ON d.id = da.dungeon_id
  JOIN attractions a ON da.attraction_id = a.no
 WHERE 1=1

     AND a.area_code = #{sidoCode}


     AND a.si_gun_gu_code = #{gugunCode}


     AND a.content_type_id = #{contentTypeId}


     AND a.title LIKE CONCAT('%', #{keyword}, '%')


     AND d.start_date >= #{startDate}


     AND d.end_date <= #{endDate}
